((root)=>{
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const imageURL=key=>key?.startsWith('/media/')?key:key==='photo'?'/assets/hero.png':['office','popup'].includes(key)?'/assets/'+key+'-3d.png':key==='a-home'?'/assets/home-3d-v2.png':key?'/assets/space-illustrations.png':'';
 const visual=(key,alt='')=>key?.startsWith('/media/')||['photo','office','popup'].includes(key)?'<img src="'+esc(imageURL(key))+'" alt="'+esc(alt)+'" loading="lazy">':key?'<div class="cms-sprite '+esc(key)+'" role="img" aria-label="'+esc(alt)+'"></div>':'<div class="cms-empty-cover">대표 사진을 선택해주세요.</div>';
 function blocks(p){return (p.blocks||p.sections?.flatMap(s=>[...(s[0]?[{type:'heading',text:s[0]}]:[]),...(s[1]?[{type:'paragraph',text:s[1]}]:[]),...(s[2]?[{type:'image',src:s[2],alt:s[0]}]:[])])||[]).map(b=>({...b,font:b.font||'inherit'}));}
 function related(p,type,pool){if(p.relatedMode!=='manual')return [];const others=pool.filter(x=>x.id!==p.id);return (p.related||[]).map(id=>others.find(x=>x.id===id)).filter(Boolean);}
 function render(p,type,pool=[],edit=false){
  const field=(key,tag,value,classes='')=>'<'+tag+' class="'+classes+'"'+(edit?' contenteditable="plaintext-only" data-edit-field="'+key+'" aria-label="'+esc(({title:'제목',lead:'짧은 소개',intro:'공간 소개',introTitle:'공간 소개 제목',flowTitle:'경험의 흐름 제목',noteTitle:'디자인 노트 제목',note:'디자인 노트',relatedTitle:'관련 글 제목'})[key]||key)+'" data-placeholder="클릭해서 내용을 입력하세요"':'')+'>'+root.NEMO_RICH.markup(p.richText?.[key],String(value??''))+'</'+tag+'>';
  const price=p.price||{},prices=type==='portfolio'&&price.mode&&price.mode!=='none'?'<dl class="cms-prices">'+(['unit','both'].includes(price.mode)&&price.unit?'<div><dt>평당 단가</dt><dd>'+esc(price.unit)+'</dd></div>':'')+(['total','both'].includes(price.mode)&&price.total?'<div><dt>총 견적</dt><dd>'+esc(price.total)+'</dd></div>':'')+'</dl>':'';
  const cover='<div class="cms-cover"'+(edit?' data-edit-cover="true" tabindex="0" aria-label="대표 사진 선택"':'')+'>'+visual(p.visual,p.title)+(edit?'<span class="cms-cover-hint">클릭해서 대표 사진 선택</span>':'')+'</div>';
  const heading='<div class="cms-heading"><span class="cms-meta">'+esc(type==='portfolio'?[p.category,p.style,p.kind,p.isActual?'프로젝트':'공간 콘셉트'].filter(Boolean).join(' · '):[p.category,(p.time||'1분')+' 읽기'].join(' · '))+'</span>'+field('title','h1',p.title||'','cms-title')+field('lead','p',p.lead||'','cms-lead')+prices+'</div>';
  const hero='<header class="cms-hero '+(type==='news'?'cms-news-hero':'')+'">'+(type==='portfolio'?cover+heading:heading+cover)+'</header>';
  const intro=type==='portfolio'?'<section class="cms-intro">'+field('introTitle','h2',p.introTitle||'공간 소개')+field('intro','p',p.intro||'')+(p.points?.length?'<div class="cms-points">'+p.points.map(s=>'<span>'+esc(s)+'</span>').join('')+'</div>':'')+'</section>':'';
  const content=blocks(p).map((b,i)=>{const controls=edit?'<div class="cms-block-tools"><span>'+({heading:'소제목',paragraph:'문단',image:'사진'})[b.type]+'</span><button type="button" data-block-action="up" data-index="'+i+'" aria-label="'+(i+1)+'번 요소 위로">↑</button><button type="button" data-block-action="down" data-index="'+i+'" aria-label="'+(i+1)+'번 요소 아래로">↓</button><button type="button" data-block-action="remove" data-index="'+i+'" aria-label="'+(i+1)+'번 요소 삭제">×</button></div>':'';
   const body=b.type==='image'?'<figure class="cms-photo cms-photo-'+(b.size||'auto')+' cms-align-'+(b.align||'center')+(b.width&&b.height&&b.width/b.height<.9?' cms-photo-portrait':'')+'">'+visual(b.src,b.alt)+'<figcaption'+(edit?' contenteditable="plaintext-only" data-block-caption="'+i+'" aria-label="사진 설명"':'')+'>'+root.NEMO_RICH.markup(b.captionRuns,String(b.alt??''))+'</figcaption></figure>':'<'+(b.type==='heading'?'h2':'p')+(edit?' contenteditable="plaintext-only" data-edit-block="'+i+'" aria-label="'+(i+1)+'번 '+(b.type==='heading'?'소제목':'문단')+'" data-placeholder="내용을 입력하세요"':'')+'>'+root.NEMO_RICH.markup(b.runs,String(b.text??''))+'</'+(b.type==='heading'?'h2':'p')+'>';
   return '<div class="cms-block '+(b.type==='image'?'cms-image-block '+(b.width&&b.height&&b.width/b.height<.9&&(!b.size||b.size==='auto')?'cms-portrait-pair ':''):'')+'cms-font-'+esc(b.font||'inherit')+'" data-block-index="'+i+'">'+controls+body+'</div>';
  }).join('');
  const narrative='<section class="cms-narrative">'+(type==='portfolio'?field('flowTitle','h2',p.flowTitle||'경험의 흐름','cms-flow-title'):'')+content+(edit?'<div class="cms-insert-end"><button type="button" data-add-block="paragraph">＋ 문단</button><button type="button" data-add-block="heading">＋ 소제목</button><button type="button" data-add-block="image">＋ 사진</button></div>':'')+'</section>';
  const note=type==='portfolio'&&p.showNote!==false?'<section class="cms-note"><span class="cms-meta">NEMO DESIGN NOTE</span>'+field('noteTitle','h2',p.noteTitle||'디자인 노트')+field('note','p',p.note??[p.lead,p.intro].filter(Boolean).join(' '))+'</section>':'';
  const chosen=related(p,type,pool),relatedSection=chosen.length?'<section class="cms-related">'+field('relatedTitle','h2',p.relatedTitle||(type==='portfolio'?'다른 공간도 살펴보세요.':'이런 이야기도 있어요.'))+'<div>'+chosen.map(x=>'<a href="/'+(type==='portfolio'?'portfolio.html?project=':'story.html?article=')+encodeURIComponent(x.id)+'">'+visual(x.visual,x.title)+'<span>'+esc(x.category)+'</span><h3>'+esc(x.title)+'</h3></a>').join('')+'</div></section>':edit?'<p class="cms-related-empty">관련 글은 오른쪽 설정에서 선택하세요.</p>':'';
  const contact='<aside class="cms-contact"><h2>생각한 공간을 함께 이야기해요.</h2><a href="/inquiry.html'+(type==='portfolio'?'?space='+encodeURIComponent(p.category)+'&amp;project='+encodeURIComponent(p.id||''):'')+'">상담 신청하기 ↗</a></aside>';
  return '<article class="cms-document cms-font-'+(p.font==='serif'?'serif':'sans')+(edit?' cms-editing':'')+'">'+hero+intro+narrative+note+relatedSection+contact+'</article>';
 }
 function layout(container){
  const imageElements=[...container.querySelectorAll('img')];
  for(const img of imageElements){const apply=()=>{if(!img.naturalWidth||!img.naturalHeight)return;const ratio=img.naturalWidth/img.naturalHeight;img.style.setProperty('--cms-native-width',img.naturalWidth+'px');const figure=img.closest('.cms-photo');if(figure){figure.classList.toggle('cms-photo-portrait',ratio<.9);figure.classList.toggle('cms-photo-wide',ratio>1.3);figure.style.setProperty('--cms-ratio',String(ratio));const block=figure.closest('.cms-image-block');block?.classList.toggle('cms-portrait-pair',ratio<.9&&figure.classList.contains('cms-photo-auto'));}const cover=img.closest('.cms-cover');if(cover){cover.classList.toggle('cms-cover-portrait',ratio<.9);cover.style.setProperty('--cms-ratio',String(ratio));}const card=img.closest('.portfolio-item');if(card&&!card.closest('.cms-related')){card.style.setProperty('--card-ratio',String(Math.max(.65,Math.min(1.8,ratio))));card.classList.toggle('card-portrait',ratio<.9);}};if(img.complete)apply();else img.addEventListener('load',apply,{once:true});
  }
 }
 root.NEMO_RENDER={render,blocks,visual,imageURL,esc,layout};
 if(typeof module!=='undefined')module.exports=root.NEMO_RENDER;
})(typeof window==='undefined'?globalThis:window);
